package contract

import (
	"os"
	"path/filepath"
	"regexp"
	"testing"
)

// TestAbigenMatchesGoMod keeps every binding generated by the go-ethereum
// release the binaries link, so make abi stays reproducible after a bump.
func TestAbigenMatchesGoMod(t *testing.T) {
	goMod, err := os.ReadFile("../../../go.mod")
	if err != nil {
		t.Fatal(err)
	}
	required := regexp.MustCompile(`(?m)^\s*github\.com/ethereum/go-ethereum (\S+)`).FindSubmatch(goMod)
	if required == nil {
		t.Fatal("go.mod does not require github.com/ethereum/go-ethereum")
	}
	directives, err := filepath.Glob("*/*_generate.go")
	if err != nil || len(directives) == 0 {
		t.Fatalf("no binding directives found: %v", err)
	}
	for _, path := range directives {
		directive, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		abigen := regexp.MustCompile(`cmd/abigen@(\S+)`).FindSubmatch(directive)
		if abigen == nil {
			t.Errorf("%s has no pinned abigen version", path)
			continue
		}
		if string(abigen[1]) != string(required[1]) {
			t.Errorf("%s runs abigen@%s, go.mod requires go-ethereum %s; update it and run make abi",
				path, abigen[1], required[1])
		}
	}
}
